    async fn get_stored_member_ids(&self) -> Result<Vec<MemberId>, ParliamentMemberRepoError> {
        sqlx::query!(
            "
            SELECT parliament_member_id
            FROM exposed.members
            ORDER BY parliament_member_id
            "
        )
        .fetch_all(self.pool())
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?
        .into_iter()
        .map(|row| {
            let parliament_id = u32::try_from(row.parliament_member_id)
                .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
            MemberId::new(parliament_id)
                .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))
        })
        .collect()
    }

    async fn get_members_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(ParliamentMember, SearchSimilarity)>, ParliamentMemberRepoError> {
        let mut tx = self
            .pool()
            .begin()
            .await
            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        sqlx::query!(
            "SELECT set_config('pg_trgm.word_similarity_threshold', $1, true)",
            word_similarity_candidate_threshold(req.strictness())
        )
        .fetch_one(&mut *tx)
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        let rows = sqlx::query!(
            "
            SELECT  
                m.name,
                m.parliament_member_id,
                m.party_name,
                m.party_id,
                m.latest_membership_from as constituency,
                 word_similarity($1, m.name) as similarity_score
            FROM exposed.members m
            WHERE m.name %> $1 AND word_similarity($1, m.name) >= $2
            ORDER BY similarity_score DESC, m.id
            LIMIT $3
            ",
            req.term(),
            req.strictness(),
            i64::from(req.max_entries())
        )
        .fetch_all(&mut *tx)
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        tx.commit()
            .await
            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        rows.into_iter()
            .map(|r| {
                let member = ParliamentMember::new(
                    r.name,
                    MemberId::new(
                        u32::try_from(r.parliament_member_id)
                            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?,
                    )
                    .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?,
                    r.party_name,
                    u32::try_from(r.party_id)
                        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?,
                    r.constituency,
                );
                let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
                Ok((member, score))
            })
            .collect()
    }

    async fn get_members_by_phonetic_search(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(ParliamentMember, PhoneticRank)>, ParliamentMemberRepoError> {
        let rows = sqlx::query!(
            r#"
            SELECT m.name, m.parliament_member_id, m.party_name, m.party_id,
                   m.latest_membership_from AS constituency,
                   d.distance AS "distance!", word_similarity($1, m.name) AS similarity_score
            FROM exposed.members m
            CROSS JOIN LATERAL (SELECT exposed.person_name_distance($1, m.name) AS distance) d
            WHERE exposed.person_name_codes(m.name) @> exposed.person_name_codes($1)
              AND d.distance IS NOT NULL
            ORDER BY d.distance, similarity_score DESC, m.parliament_member_id
            LIMIT $2
            "#,
            req.term(),
            i64::from(req.max_entries())
        )
        .fetch_all(self.pool())
        .await
        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?;
        rows.into_iter()
            .map(|r| {
                let member = ParliamentMember::new(
                    r.name,
                    MemberId::new(
                        u32::try_from(r.parliament_member_id)
                            .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?,
